import{c as t,Q as a,j as n,m as i}from"./chunks/framework.BXc4yaFE.js";const m=JSON.parse('{"title":"Scaling Monosemanticity: Extracting Interpretable Features from Claude 3 Sonnet","description":"","frontmatter":{"url":"https://transformer-circuits.pub/2024/scaling-monosemanticity/","title":"Scaling Monosemanticity: Extracting Interpretable Features from Claude 3 Sonnet","archived_date":"2026-06-09T00:00:00.000Z","authors":["Adly Templeton","Tom Conerly","Jonathan Marcus","Jack Lindsey","Trenton Bricken","Brian Chen","Adam Pearce","Craig Citro","Emmanuel Ameisen","Andy Jones","Hoagy Cunningham","Nicholas L Turner","Callum McDougall","Monte MacDiarmid","Alex Tamkin","Esin Durmus","Tristan Hume","Francesco Mosconi","C. Daniel Freeman","Theodore R. Sumers","Edward Rees","Joshua Batson","Adam Jermyn","Shan Carter","Chris Olah","Tom Henighan"],"published_date":"2024-01-01T00:00:00.000Z"},"headers":[],"relativePath":"research/papers/2024-05-23-scaling-monosemanticity-claude3-sonnet.md","filePath":"research/papers/2024-05-23-scaling-monosemanticity-claude3-sonnet.md","lastUpdated":1785909234000}'),r={name:"research/papers/2024-05-23-scaling-monosemanticity-claude3-sonnet.md"};function s(o,e,l,c,u,d){return a(),n("div",null,[...e[0]||(e[0]=[i('<h1 id="scaling-monosemanticity-extracting-interpretable-features-from-claude-3-sonnet" tabindex="-1">Scaling Monosemanticity: Extracting Interpretable Features from Claude 3 Sonnet <a class="header-anchor" href="#scaling-monosemanticity-extracting-interpretable-features-from-claude-3-sonnet" aria-label="Permalink to &quot;Scaling Monosemanticity: Extracting Interpretable Features from Claude 3 Sonnet&quot;">​</a></h1><p><strong>Authors:</strong> Adly Templeton, Tom Conerly, Jonathan Marcus, Jack Lindsey, Trenton Bricken, Brian Chen, Adam Pearce, Craig Citro, Emmanuel Ameisen, Andy Jones, Hoagy Cunningham, Nicholas L Turner, Callum McDougall, Monte MacDiarmid, Alex Tamkin, Esin Durmus, Tristan Hume, Francesco Mosconi, C. Daniel Freeman, Theodore R. Sumers, Edward Rees, Joshua Batson, Adam Jermyn, Shan Carter, Chris Olah, Tom Henighan</p><p><strong>Year:</strong> 2024</p><p><strong>Venue/Publisher:</strong> Transformer Circuits Thread (Anthropic)</p><p><strong>ArXiv:</strong> N/A (published at transformer-circuits.pub)</p><p><strong>URL:</strong> <a href="https://transformer-circuits.pub/2024/scaling-monosemanticity/" target="_blank" rel="noreferrer">https://transformer-circuits.pub/2024/scaling-monosemanticity/</a></p><hr><h2 id="abstract" tabindex="-1">Abstract <a class="header-anchor" href="#abstract" aria-label="Permalink to &quot;Abstract&quot;">​</a></h2><p>This paper demonstrates that sparse autoencoders scale successfully to production-level large language models. The authors trained SAEs on the middle-layer residual stream of Claude 3 Sonnet and extracted 34 million latent features. They demonstrate that scaling laws apply to SAE training and that the extracted features at this scale are highly abstract and diverse — responding to and causally influencing complex behaviors. The work addresses the key open question of whether monosemantic feature extraction was feasible for frontier models, and provides the first window into the internal feature representations of a state-of-the-art commercial LLM.</p><hr><h2 id="key-contributions" tabindex="-1">Key Contributions <a class="header-anchor" href="#key-contributions" aria-label="Permalink to &quot;Key Contributions&quot;">​</a></h2><ul><li><strong>First demonstration that sparse autoencoders scale to production frontier LLMs</strong> (Claude 3 Sonnet), extracting 34 million features — a 4,000× expansion over prior one-layer experiments and the first interpretability result on a state-of-the-art commercial model</li><li><strong>Empirical evidence that SAE training follows predictable scaling laws</strong>, enabling principled SAE design: loss decreases as a power law in both number of features and amount of training data</li><li><strong>Discovery of highly abstract, multimodal features</strong> encoding concepts like emotions, ethical stances, bias, country-specific associations, and safety-relevant behaviors that span text and (in some cases) visual modalities</li><li><strong>Feature steering experiments</strong> showing causal control over model behavior by directly activating or suppressing individual features, including demonstrations that activating a &quot;banana&quot; feature causes the model to write about bananas regardless of prompt context</li><li><strong>Interpretability of safety-critical features</strong> including features for deception, manipulation, dangerous knowledge domains, and potential indicators of model self-representation — directly relevant to AI safety</li><li><strong>Quantitative evaluation framework</strong> for feature quality at scale using automated interpretability scoring with LLM judges, enabling systematic comparison across SAE sizes</li><li><strong>Middle-layer residual stream focus</strong>: demonstrates that residual stream activations (rather than MLP outputs alone) are a viable and information-rich target for SAE training at scale</li></ul><hr><h2 id="methodology" tabindex="-1">Methodology <a class="header-anchor" href="#methodology" aria-label="Permalink to &quot;Methodology&quot;">​</a></h2><p>The authors train sparse autoencoders on the <strong>residual stream activations</strong> at the middle layer of Claude 3 Sonnet. The SAE architecture follows the approach established in &quot;Towards Monosemanticity&quot; but with significant engineering adaptations for scale: the model has billions of parameters, and the training dataset consists of a large corpus of text drawn from Claude&#39;s training distribution. SAEs of varying sizes — from 1 million to 34 million features — are trained, enabling the empirical study of scaling laws.</p><p>The key training challenge at this scale is computational: training a 34-million-feature SAE on a frontier model requires processing billions of activations and managing a dictionary that is orders of magnitude larger than a model&#39;s neuron count. The authors use efficient batched training with careful learning rate scheduling and sparsity tuning. The L1 penalty coefficient is calibrated to achieve a target sparsity level (typically 20–100 active features per token), balancing reconstruction quality against feature interpretability. The resulting SAEs are evaluated on held-out activations using the fraction of variance explained and the L0 norm (average number of active features).</p><p>For feature interpretation, the authors use a combination of <strong>maximum activating example analysis</strong> (finding input texts that activate each feature most strongly), <strong>automated interpretability scoring</strong> (prompting a separate LLM to predict feature activations from a proposed interpretation and comparing against ground truth), and <strong>causal intervention experiments</strong> (directly clamping feature activation values to high or low values and measuring effects on model outputs). The causal steering methodology is extended to study multi-feature interactions: activating a cluster of related features produces coherent thematic shifts in model outputs.</p><hr><h2 id="main-results" tabindex="-1">Main Results <a class="header-anchor" href="#main-results" aria-label="Permalink to &quot;Main Results&quot;">​</a></h2><ul><li>SAEs with up to <strong>34 million features</strong> were successfully trained on Claude 3 Sonnet residual stream activations, with reconstruction quality (fraction of variance explained) exceeding 60% for the largest models</li><li>SAE training loss follows a <strong>predictable power law</strong> in both number of features and training tokens, suggesting that SAE capability can be forecast without exhaustive grid search</li><li>Features at this scale are <strong>qualitatively more abstract</strong> than those found in one-layer models: rather than specific token patterns, they encode concepts like &quot;the Golden Gate Bridge,&quot; &quot;the concept of trust,&quot; &quot;the emotion of frustration,&quot; and country-specific cultural associations</li><li><strong>Safety-relevant features were discovered</strong>, including features that activate on text about deception, manipulation tactics, dangerous chemical synthesis, and potential self-referential features encoding the model&#39;s own identity</li><li><strong>Feature steering demonstrations</strong>: directly activating the &quot;banana&quot; feature caused the model to spontaneously write about bananas; activating a &quot;Golden Gate Bridge&quot; feature caused persistent self-identification as the bridge across conversation turns</li><li>Automated interpretability scores are substantially higher for SAE features than for individual neurons at matched computational cost, confirming that monosemanticity scales</li><li>Features show <strong>cross-lingual generalization</strong>: a feature that activates on English text about a concept often activates on equivalent text in French, Spanish, Chinese, and other languages</li></ul><hr><h2 id="limitations-future-work" tabindex="-1">Limitations &amp; Future Work <a class="header-anchor" href="#limitations-future-work" aria-label="Permalink to &quot;Limitations &amp; Future Work&quot;">​</a></h2><ul><li>Analysis is limited to a <strong>single middle layer</strong> of Claude 3 Sonnet; how features in different layers interact, and whether the full model can be understood layer by layer, remains open</li><li><strong>34 million features may still be incomplete</strong>: the model likely represents far more distinct concepts, and the relationship between SAE dictionary completeness and model capability is unknown</li><li>Causal steering experiments show that features influence behavior, but <strong>multi-feature interactions</strong> are complex — activating one feature can suppress or amplify related features in ways that are not fully characterized</li><li>The <strong>computational cost</strong> of training and storing 34-million-feature SAEs is substantial, potentially limiting accessibility for researchers without Anthropic-scale resources</li><li><strong>Attention heads are not studied</strong>; all results concern MLP/residual stream features, leaving attention mechanisms as a major interpretability gap</li><li>Safety-relevant features are identified but <strong>no mechanistic account</strong> of how those features are computed from inputs or how they influence outputs is given — that circuit-level account is addressed in subsequent attribution graph work</li></ul><hr><h2 id="why-this-matters-for-ai-practitioners" tabindex="-1">Why This Matters for AI Practitioners <a class="header-anchor" href="#why-this-matters-for-ai-practitioners" aria-label="Permalink to &quot;Why This Matters for AI Practitioners&quot;">​</a></h2><p>This paper is a landmark result demonstrating that mechanistic interpretability is not limited to toy models or simple architectures — it scales to frontier commercial LLMs. The discovery of 34 million interpretable features inside Claude 3 Sonnet fundamentally changes the AI safety landscape: it is now empirically established that production models represent human-understandable concepts internally, and that those internal representations can be accessed and steered from outside.</p><p>For AI safety researchers, the identification of safety-critical features (deception, manipulation, dangerous knowledge) raises the possibility of <strong>interpretability-based monitoring</strong>: deploying SAEs as inference-time probes to detect when a model is internally representing dangerous concepts, even if its output appears benign. The feature steering results demonstrate that these are not passive observations but active levers.</p><p>For ML engineers, the scaling laws result is practically valuable: it means SAE training can be planned and budgeted using predictable power-law extrapolations rather than expensive exploratory sweeps. The open question of whether these results replicate across model families (GPT, Gemini, Llama) and architectures makes this a natural starting point for cross-model interpretability audits.</p>',28)])])}const g=t(r,[["render",s]]);export{m as __pageData,g as default};
